python
def paidReservationsThresholdFile(drawers, k):
    a=drawers
    out=[]
    rows=sorted(a,key=lambda r:(r[1],r[0],r[2]))
    dp=[0]
    for i,(start,end,reward) in enumerate(rows):
        left,right=0,i
        while left<right:
            mid=(left+right)//2
            if rows[mid][1]<=start: left=mid+1
            else: right=mid
        dp.append(max(dp[i],dp[left]+reward))
    out=dp[1:]
    return sum(x>=k for x in out)


java
class Solution {
  public int paidReservationsThresholdFile(int[][] drawers, int k) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {int[][]rows=a.clone();Arrays.sort(rows,Comparator.comparingInt((int[]r)->r[1]).thenComparingInt(r->r[0]).thenComparingInt(r->r[2]));int[]dp=new int[rows.length+1];for(int i=0;i<rows.length;i++){int l=0,r=i;while(l<r){int m=(l+r)/2;if(rows[m][1]<=rows[i][0])l=m+1;else r=m;}dp[i+1]=Math.max(dp[i],dp[l]+rows[i][2]);out.add(dp[i+1]);}}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
